                          <input class="form-control" type="number" step="any" placeholder="Enter." v-model="charge">
                        </div>


                          <div class="col-md-4">
                          <label class="form-label">Licence</label>
                          <input class="form-control" type="number" step="any" placeholder="Enter." v-model="licence">
                        </div>

                        <div class="col-md-12">
                          <label class="form-label">Offence</label>
                          <input class="form-control" type="text" placeholder="Enter." v-model="offence">
                        </div>

