      <div class="modal-footer">
        <button type="button" class="btn btn-danger btn-sm py-2 px-2" data-bs-dismiss="modal" @click="clearFine()">Close</button>
        <button type="submit" class="btn btn-success btn-sm py-2 px-2" @click="printFine(fine)">
        <i class="bi bi-printer fs-5"/>
        </button>

      </div>
    </div>
