<script setup>
import { onMounted, ref, inject, computed, watch } from 'vue';
import axios from 'axios';
import { useMeta } from '@/composables/use-meta';
import Multiselect from '@suadelabs/vue3-multiselect';
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
import PaymentProofModal from '../components/TrafficFineProofOfPaymentModal.vue';
import { useRoute } from 'vue-router';
const openModalOnModal = inject('openModalOnModal');
const waitIndicator = inject('waitIndicator')
const route = useRoute();
useMeta({ title: 'Work Plans' });

const showMessage  = inject('showMessage');
const showError    = inject('showError');
const formatNumber = inject('formatNumber');
const formatRate = inject('formatRate');
const showConfirmation = inject('showConfirmation');
const loadingSpinner   = inject('loadingSpinner');
const doubleSpinner   = inject('doubleSpinner');
const tableShimmer      = inject('tableShimmer');
const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;

    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 , 100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['id', 'service_name'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

const loading            = ref(false);
const axiosInstance = axios.create({ baseURL: process.env.VUE_APP_API_BASE_URL });

const assets = ref([])
const asset = ref('')
const getAssets = async ()=>{
    const response = await axiosInstance.get('machines')
    assets.value = response.data.map((item)=>({
        ...item,
        name : item.name + ' '+ item.type_name
    }))
}

const columns = ref(['Sno','vehicle','licence','location', 'offence','date','amount','note','status','actions']);
const fines = ref([])
const getTrafficFines = async()=>{
    try{
         loading.value = true
         const response = await axiosInstance.get('traffic-fines')
         fines.value = response.data.map((item,index)=>({
            ...item,
            Sno : index + 1,
            vehicle : item.asset.name,
            amount : formatNumber(item.amount),
            note : item.note ?? "---"
         }))
    }catch(error){
        console.log(error)
        showError(error.message)
    }finally{
        loading.value = false
    }
}

const licence = ref('')
const offence = ref('')
const date = ref('')
const charge = ref('')
const location = ref('')
const control_number = ref('')

const clearForm = ()=>{
      licence.value = '',
      offence.value = '',
      date.value = '',
      charge.value = '',
      location.value = '',
      control_number.value = '',
      asset.value = ''
      loading.value = false
      document.getElementById('close-form').click()
}

const fine = ref('')
const clearFine = ()=>{
  fine.value = '',
  penalties.value = []
}
const registerTrafficFines = async()=>{
      loading.value = true
  const payload = {
      licence : licence.value,
      offence : offence.value,
      date : date.value,
      charge : charge.value,
      location : location.value,
      control_number : control_number.value,
      asset_id : asset.value.id,
      issuer_id : JSON.parse(localStorage.getItem('user')).id
  }
  try{
     const response = await axiosInstance.post('traffic-fines',payload)
     showMessage('Fine Saved Successfully!')
     getTrafficFines()
  }catch(error){
    console.log(error)
    showError(error.message)
  }finally{
          clearForm()
  }
  console.log(payload)
}


const printFine = async (fine) => {
    try {
        const iframe = document.createElement("iframe");
        iframe.style.display = "none";
        document.body.appendChild(iframe);

        const penaltyList = Array.isArray(penalties) ? penalties : (penalties?.value || []);

        const charge = Number(fine.charge || 0);

        const totalPenalties = penaltyList.reduce(
            (total, penalty) => total + Number(penalty.rate || 0), 0
        );

        const grandTotal = charge + totalPenalties;

        const money = (amount) => Number(amount || 0).toLocaleString('en-US');

        const printContent = `
<!DOCTYPE html>
<html>
<head>
<title>Traffic Fine Report</title>
<style>
  body {
    font-family: 'Courier New', monospace;
    margin: 40px;
    font-size: 13px;
  }

  .text-style { font-family: 'Courier New', monospace; }
  .company-title { text-align: center; }
  .title { text-align: center; font-size: 20px; margin: 10px 0; }

  table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 20px;
  }

  th, td {
    border: 0.5px solid #000;
    padding: 8px;
    text-align: left;
  }

  th {
    background-color: #f8f8f8;
    font-weight: bold;
  }

  .text-center { text-align: center; }

  hr {
    border: 0;
    border-top: 0.5px solid #000;
    margin: 10px 0;
  }

  .section-title {
    font-weight: bold;
    font-size: 16px;
    margin-top: 25px;
    margin-bottom: 10px;
  }

  .amount {
    text-align: right;
  }

  .grand-total th {
    font-size: 15px;
    padding: 12px 8px;
  }

  @media print {
    body { margin: 10mm; }
    table { page-break-inside: auto; }
    tr { page-break-inside: avoid; }
  }
</style>
</head>

<body>

<div class="company-title text-style">
  <i>
    <h1>COPEX CONTRACTORS CO.LTD</h1>
    <div><b>Address:</b> Msamvu, P.O.BOX 678, Morogoro</div>
    <div><b>Tel:</b> 0713 000 777, 0657 111 555</div>
    <div><b>Email:</b> info@copexcontractors.co.tz</div>
    <div><b>TIN:</b> 135-489-247 &nbsp;&nbsp; <b>VRN:</b> 40-032826C</div>
  </i>
</div>

<hr style="margin-top:20px">

<div class="title text-style">
  TRAFFIC FINE REPORT
</div>

<hr>

<div class="section-title">
  FINE DETAILS
</div>

<table>
  <thead>
    <tr>
      <th style="width:25%">Description</th>
      <th>Details</th>
    </tr>
  </thead>

  <tbody>
    <tr>
      <th>Fine ID</th>
      <td>TF-${fine.id || 'N/A'}</td>
    </tr>
    <tr>
      <th>Vehicle / Asset</th>
      <td>${fine.vehicle || 'N/A'}</td>
    </tr>
    <tr>
      <th>Licence</th>
      <td>${fine.licence || 'N/A'}</td>
    </tr>
    <tr>
      <th>Location</th>
      <td>${fine.location || 'N/A'}</td>
    </tr>
    <tr>
      <th>Date</th>
      <td>${fine.date || 'N/A'}</td>
    </tr>
    <tr>
      <th>Designated To</th>
      <td>${fine.note || 'N/A'}</td>
    </tr>
    <tr>
      <th>Offence</th>
      <td>${fine.offence || 'N/A'}</td>
    </tr>
    <tr>
      <th>Control Number</th>
      <td>${fine.control_number || 'N/A'}</td>
    </tr>
  </tbody>
</table>

<div class="section-title">
  PENALTIES
</div>

<table>
  <thead>
    <tr>
      <th style="width:10%">#</th>
      <th>Penalty Date</th>
      <th>Issued By</th>
      <th class="amount">Amount (TZS)</th>
    </tr>
  </thead>

  <tbody>
    ${penaltyList.length ? penaltyList.map((penalty, index) => `
      <tr>
        <td>${index + 1}</td>
        <td>${penalty.date || 'N/A'}</td>
        <td>${penalty.issuer || 'N/A'}</td>
        <td class="amount">${money(penalty.rate)}</td>
      </tr>
    `).join('') : `
      <tr>
        <td colspan="4" class="text-center">No penalties recorded</td>
      </tr>
    `}

    <tr>
      <th colspan="3" class="amount">TOTAL PENALTIES</th>
      <th class="amount">${money(totalPenalties)}</th>
    </tr>
  </tbody>
</table>

<div class="section-title">
  FINANCIAL SUMMARY
</div>

<table>
  <tbody>
    <tr>
      <td>Original Fine / Charge</td>
      <td class="amount">${money(charge)} TZS</td>
    </tr>

    <tr>
      <td>Additional Penalties</td>
      <td class="amount">${money(totalPenalties)} TZS</td>
    </tr>

    <tr class="grand-total">
      <th>GRAND TOTAL (CHARGE + PENALTIES)</th>
      <th class="amount">${money(grandTotal)} TZS</th>
    </tr>
  </tbody>
</table>

<table style="margin-top:50px;">
  <tbody>
    <tr>
      <td class="text-center" style="border:none;">Prepared By</td>
      <td class="text-center" style="border:none;">Approved By</td>
    </tr>

    <tr>
      <td style="border-bottom:1px solid #000;border-top:1px solid #fff;border-right:1px solid #fff;border-left:1px solid #fff;" class="text-center">
        __________________________
      </td>
      <td style="border-bottom:1px solid #000;border-top:1px solid #fff;border-right:1px solid #fff;border-left:1px solid #fff;" class="text-center">
        __________________________
      </td>
    </tr>

    <tr>
      <th style="border:none;" class="text-center">HR</th>
      <th style="border:none;" class="text-center">DIRECTOR</th>
    </tr>
  </tbody>
</table>

<div style="margin-top:15px; font-size:7px;">
  <p><strong>Report Generated:</strong> ${new Date().toLocaleString()}</p>
  <p><strong>Generated By:</strong> ${JSON.parse(localStorage.getItem('user')).name}</p>
</div>

</body>
</html>
`;

        const iframeDoc = iframe.contentWindow.document;
        iframeDoc.open();
        iframeDoc.write(printContent);
        iframeDoc.close();

        iframe.onload = () => {
            iframe.contentWindow.focus();
            iframe.contentWindow.print();

            setTimeout(() => {
                document.body.removeChild(iframe);
            }, 1000);
        };

    } catch (error) {
        console.error('Print error:', error);
        showError(`Failed to print fine: ${error.message}`);
    }
};


const addPenalty = ref(false)
const rate = ref('')
const registerTrafficPenalty= async()=>{
  loading.value = true
  const payload = {
    issuer_id : JSON.parse(localStorage.getItem('user')).id,
    rate : rate.value,
    source : "penalty",
    entry_id : fine.value.id,
    date : date.value
  }
  try{
    const response = await axiosInstance.post('entry-items',payload)
    showMessage('Penalty saved!')
    getPenalties(fine.value.id)
    getTrafficFines()
  }catch(error){
    console.log(error)
    showError(error.message)
  }finally{
    loading.value = false
    rate.value = '',
    date.value = '',
    addPenalty.value = false
  }
}

const penalties = ref([])
const getPenalties = async(id)=>{
  try{
    loading.value = true
  const response = await axiosInstance.get(`entry-items?source=penalty&entry_id=${id}`)
  penalties.value = response.data
  }catch(error){
    console.log(error)
    showError(error.message)
  }finally{
    loading.value = false
  }

}

const editNote = ref(false)
const editing = ref(false)
const editDesignator = async(fine)=>{
  const payload = {
    remark : fine.note
  }
  try{
    editing.value = true
   const response = await axiosInstance.put(`entries/${fine.id}`,payload)
  showMessage('Designator Updated!')
  editNote.value = false
  getTrafficFines()
  }catch(error){
    console.log(error)
    showError(error.message)
  }finally{
    editing.value = false
  }
}

onMounted(() => {
  getAssets()
  getTrafficFines()
});







</script>

