<template>


                 <div class="modal fade mymodal" id="payment-proof" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel">Traffic Fine proof Of Payment</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close_modal" @click="clearForm()"></button>
      </div>

<form @submit.prevent="addProofOfPaymnet()">

    <div class="modal-body" >
       <div class="row me-5">
  <div class="col-md-4">
    <label class="form-label">Amount</label>
    <input type="number" class="form-control" placeholder="amount" required v-model="amount">
  </div>

    <div class="col-md-4">
    <label class="form-label"> Date</label>
    <input type="date" class="form-control" placeholder="date" required v-model="date">
  </div>


         <div class="col-md-4">
    <label for="attachment">Attachment</label>
    <input
        type="file"
        @change="handleAttachment"
        class="form-control"
        id="attachment"
    >
</div>


</div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-danger me-2" data-bs-dismiss="modal" @click="clearForm()">Close</button>
       <button class="btn btn-primary" type="submit" :disabled="loading">
          <span v-if="isSending" v-html="loadingSpinner()"></span>
          <span v-else>Submit</span>
        </button>
    </div>
</form>

    </div>
  </div>

</div>




</template>


<script setup>
    import { onMounted, ref, inject, watch, computed } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Budget Editing' });
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const formatDate = inject('formatDate')
const user_id = JSON.parse(localStorage.getItem("user")).id
const user_permissions = JSON.parse(localStorage.getItem('user')).permissions
const props = defineProps({
    entryId : String
});
const emit = defineEmits(['saved'])


const showError = inject('showError')
const showMessage = inject('showMessage')
const waitIndicator = inject('waitIndicator')
const loadingSpinner = inject('loadingSpinner')

const order_id = ref('')
const date = ref('')
const amount = ref('')
const rate = ref('')

const loading = ref(false)

const clearForm = ()=>{
 amount.value = '',
 date.value = '',
 attachment.value  = '';
}


  const attachment = ref('');
    const handleAttachment = (e) => {
    attachment.value = e.target.files[0];
};


const isSending = ref('');
const addProofOfPaymnet = async () => {
    isSending.value = true;
    const formData = new FormData();
    formData.append('type_id', props.entryId);
    formData.append('date', date.value);
    formData.append('description', amount.value);
    formData.append('issuer_id', user_id);
    formData.append('path', attachment.value);
    formData.append('type', 'traffic_fine');

    try {
        const response = await axiosInstance.post(
            'attachments',
            formData,
            { headers: { 'Content-Type': 'multipart/form-data' } }
        );
        showMessage('submitted successfull');
        document.getElementById('close_modal').click();
        emit('saved', response.data);
        clearForm();
        
    } catch (error) {
        showError(error.message);
        console.log(error);
   } finally {
        isSending.value = false;
    }
};


    onMounted(async() => {
      //  getLogs('LPO',3418)
    });
</script>







